   1: using System.Collections.Concurrent;
   2: using System.Security.Cryptography;
   3: 
   4: namespace InvoiceApp.Api.Auth;
   5: 
   6: /// <summary>Keeps signed-in sessions in memory, keyed by an opaque bearer token.</summary>
   7: public class SessionStore
   8: {
   9:     private readonly ConcurrentDictionary<string, UserSession> _sessions = new();
  10: 
  11:     public string Create(UserSession session)
  12:     {
  13:         var token = Convert.ToHexString(RandomNumberGenerator.GetBytes(16));
  14:         _sessions[token] = session;
  15:         return token;
  16:     }
  17: 
  18:     public UserSession? Get(string? token) =>
  19:         token is not null && _sessions.TryGetValue(token, out var session) ? session : null;
  20: 
  21:     public void Remove(string token) => _sessions.TryRemove(token, out _);
  22: }

