  16: 
  17:     public override void OnActionExecuting(ActionExecutingContext context)
  18:     {
  19:         var session = context.HttpContext.Items[HttpContextExtensions.SessionKey] as UserSession;
  20: 
  21:         if (session is null || !_roles.Contains(session.Role))
  22:         {
  23:             context.Result = new StatusCodeResult(StatusCodes.Status403Forbidden);
  24:         }
  25:     }
