   1: using InvoiceApp.Domain;
   2: 
   3: namespace InvoiceApp.Api;
   4: 
   5: /// <summary>In-memory store so the demo app runs with no database. Seeded with a few invoices.</summary>
   6: public class InMemoryInvoiceRepository : IInvoiceRepository
   7: {
   8:     private readonly object _lock = new();
   9:     private int _nextNumber = 1006;
  10: 
  11:     private readonly List<Invoice> _invoices = new()
  12:     {
  13:         new Invoice { Id = "INV-1001", CustomerName = "Lakeside School District", Amount = 4250.00m, Status = InvoiceStatus.PendingApproval },
  14:         new Invoice { Id = "INV-1002", CustomerName = "Hilltop Academy", Amount = 980.50m, Status = InvoiceStatus.PendingApproval },
  15:         new Invoice { Id = "INV-1003", CustomerName = "Riverside Charter", Amount = 12300.00m, Status = InvoiceStatus.Approved, DecidedBy = "demo.approver", DecidedAt = DateTime.UtcNow.AddDays(-2) },
  16:         new Invoice { Id = "INV-1004", CustomerName = "Oakwood Independent", Amount = 615.75m, Status = InvoiceStatus.PendingApproval },
  17:         new Invoice { Id = "INV-1005", CustomerName = "Maple Grove Prep", Amount = 310.00m, Status = InvoiceStatus.Draft },
  18:     };
  19: 
  20:     public IReadOnlyList<Invoice> GetAll()
  21:     {
  22:         lock (_lock) return _invoices.ToList();
  23:     }
  24: 
  25:     public Invoice? GetById(string id)
  26:     {
  27:         lock (_lock) return _invoices.FirstOrDefault(i => i.Id == id);
  28:     }
  29: 
  30:     public IReadOnlyList<Invoice> GetByIds(IEnumerable<string> ids)
  31:     {
  32:         var wanted = ids.ToHashSet();
  33:         lock (_lock) return _invoices.Where(i => wanted.Contains(i.Id)).ToList();
  34:     }
  35: 
  36:     public Invoice Add(Invoice invoice)
  37:     {
  38:         lock (_lock)
  39:         {
  40:             if (string.IsNullOrEmpty(invoice.Id))
  41:             {
  42:                 invoice.Id = $"INV-{_nextNumber++}";
  43:             }
  44: 
  45:             _invoices.Add(invoice);
  46:             return invoice;
  47:         }
  48:     }
  49: 
  50:     public void Update(Invoice invoice)
  51:     {
  52:         lock (_lock)
  53:         {
  54:             var index = _invoices.FindIndex(i => i.Id == invoice.Id);
  55:             if (index >= 0) _invoices[index] = invoice;
  56:         }
  57:     }
  58: 
  59:     public bool Remove(string id)
  60:     {
  61:         lock (_lock) return _invoices.RemoveAll(i => i.Id == id) > 0;
  62:     }
  63: }

===== backend/src/InvoiceApp.Domain/ApprovalService.cs =====
   1: namespace InvoiceApp.Domain;
   2: 
   3: /// <summary>
   4: /// Moves an invoice through its lifecycle: Draft -> PendingApproval -> Approved or Rejected.
   5: /// One invoice at a time, decided as a whole by a single approver.
   6: /// </summary>
   7: public class ApprovalService
   8: {
   9:     private readonly IInvoiceRepository _repository;
  10: 
  11:     public ApprovalService(IInvoiceRepository repository)
  12:     {
  13:         _repository = repository;
  14:     }
  15: 
  16:     public Invoice Submit(string invoiceId)
  17:     {
  18:         var invoice = Find(invoiceId);
  19: 
  20:         if (invoice.Status != InvoiceStatus.Draft)
  21:         {
  22:             throw new InvalidOperationException(
  23:                 $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
  24:         }
  25: 
  26:         invoice.Status = InvoiceStatus.PendingApproval;
  27:         _repository.Update(invoice);
  28:         return invoice;
  29:     }
  30: 
  31:     public Invoice Approve(string invoiceId, string approver)
  32:     {
  33:         var invoice = Find(invoiceId);
  34:         EnsurePending(invoice);
  35: 
  36:         invoice.Status = InvoiceStatus.Approved;
  37:         invoice.DecidedBy = approver;
  38:         invoice.DecidedAt = DateTime.UtcNow;
  39:         _repository.Update(invoice);
  40:         return invoice;
  41:     }
  42: 
  43:     public Invoice Reject(string invoiceId, string approver, string reason)
  44:     {
  45:         if (string.IsNullOrWhiteSpace(reason))
  46:         {
  47:             throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
  48:         }
  49: 
  50:         var invoice = Find(invoiceId);
  51:         EnsurePending(invoice);
  52: 
  53:         invoice.Status = InvoiceStatus.Rejected;
  54:         invoice.DecidedBy = approver;
  55:         invoice.DecidedAt = DateTime.UtcNow;
  56:         invoice.DecisionNote = reason;
  57:         _repository.Update(invoice);
  58:         return invoice;
  59:     }
  60: 
  61:     private Invoice Find(string invoiceId) =>
  62:         _repository.GetById(invoiceId)
  63:         ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");
  64: 
  65:     private static void EnsurePending(Invoice invoice)
  66:     {
  67:         if (invoice.Status != InvoiceStatus.PendingApproval)
  68:         {
  69:             throw new InvalidOperationException(
  70:                 $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
  71:         }
  72:     }
  73: }

