   3: /// <summary>Requires a valid bearer token on every /api call except sign-in.</summary>
   4: public class SessionAuthMiddleware
   5: {
   6:     private const string BearerPrefix = "Bearer ";
   7:     private readonly RequestDelegate _next;
   8:     private readonly SessionStore _sessions;
   9: 
  10:     public SessionAuthMiddleware(RequestDelegate next, SessionStore sessions)
  11:     {
  12:         _next = next;
  13:         _sessions = sessions;
  14:     }
  15: 
  16:     public async Task InvokeAsync(HttpContext context)
  17:     {
  18:         var path = context.Request.Path;
  19:         var needsSession = path.StartsWithSegments("/api") && !path.StartsWithSegments("/api/auth/login");
  20: 
  21:         if (needsSession)
  22:         {
  23:             var header = context.Request.Headers.Authorization.ToString();
  24:             var token = header.StartsWith(BearerPrefix) ? header[BearerPrefix.Length..] : null;
  25:             var session = _sessions.Get(token);
  26: 
  27:             if (session is null)
  28:             {
  29:                 context.Response.StatusCode = StatusCodes.Status401Unauthorized;
  30:                 return;
  31:             }
  32: 
  33:             context.Items[HttpContextExtensions.SessionKey] = session;
  34:         }
  35: 
  36:         await _next(context);
  37:     }
  38: }
  39: 
  40: public static class HttpContextExtensions
  41: {
  42:     public const string SessionKey = "session";
  43: 
  44:     public static UserSession GetSession(this HttpContext context) =>
  45:         (UserSession)context.Items[SessionKey]!;
  46: }

